    def punishmentNumber(self, n: int) -> int:
        def can_partition(s, pos, target, cur):
            if pos == len(s):
                return cur == target
            val = 0
            for end in range(pos, len(s)):
                val = val * 10 + int(s[end])
                if cur + val > target:
                    break
                if can_partition(s, end + 1, target, cur + val):
                    return True
            return False

        total = 0
        for i in range(1, n + 1):
            sq = i * i
            if can_partition(str(sq), 0, i, 0):
                total += sq
        return total
