    def punishmentNumber(self, n: int) -> int:
        def can(s, idx, target):
            # s: digit string, idx: current position, target: remaining sum needed
            if idx == len(s):
                return target == 0
            val = 0
            for j in range(idx, len(s)):
                val = val * 10 + (ord(s[j]) - ord('0'))
                if val > target:
                    break
                if can(s, j + 1, target - val):
                    return True
            return False

        total = 0
        for i in range(1, n + 1):
            sq = str(i * i)
            if can(sq, 0, i):
                total += i * i
        return total
