            L = len(s)

            def dfs(pos, total):
                if pos == L:
                    return total == target
                if total > target:
                    return False
                val = 0
                for j in range(pos, L):
                    val = val * 10 + (ord(s[j]) - ord('0'))
                    if total + val > target:
                        break
                    if dfs(j + 1, total + val):
                        return True
                return False

            return dfs(0, 0)

        result = 0
        for i in range(1, n + 1):
            sq = i * i
            if can_partition(str(sq), i):
                result += sq
        return result
