def ref(inp):
    n = int(inp.strip())

    def good(i):
        s = str(i * i)
        L = len(s)
        # try every way to place cut points between the L-1 gaps
        for mask in range(1 << (L - 1)):
            total = 0
            start = 0
            for pos in range(1, L):
                if mask >> (pos - 1) & 1:
                    total += int(s[start:pos])
                    start = pos
            total += int(s[start:])
            if total == i:
                return True
        return False

    result = 0
    for i in range(1, n + 1):
        if good(i):
            result += i * i
    return json.dumps(result)
